    line=Counter(x for r in g for x in r if x!=bg).most_common(1)[0][0]
    blocks=[]
    for r in range(h-2):
        for c in range(w-2):
            if all(g[rr][cc]==line for rr in range(r,r+3) for cc in range(c,c+3)):
                blocks.append((r,c))
    blocked={(rr,cc) for r,c in blocks for rr in range(r,r+3) for cc in range(c,c+3)}
    seen=set(); colors=[]
    for r in range(h):
